contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // call go with arbitrary amount; ensure we have the funds to send
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // observe balance before
        uint balBefore = address(c).balance;

        // perform the call and record whether it reverted
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(c).balance;

        // General property: the call must not increase c's balance, and it must not revert.
        // i.e., balAfter <= balBefore and reverted == false
        assert(balAfter <= balBefore && reverted == false);
    }

    receive() external payable {}
}

